"""Gets the sum of all numbers up to the provided number."""
def gaussian_sum(number: int) -> int {
    number * (1 + number) // 2
}

"""Determine whether the Vim script function with the given name is public."""
def is_public_function(function_name: str) -> bool {
    is_global_function = ':' not in function_name and function_name[0].isupper();
    is_autoload_function = '#' in function_name and not function_name[0].isupper();
    return is_global_function or is_autoload_function;
}

"""Parse the test time set in the yaml configuration file and convert it to int type."""
def timestr_to_int(time_str: int | str) -> int {
    if isinstance(time_str, int) or time_str.isdigit() {
        time_int = int(time_str);
    } elif time_str.endswith("s") {
        time_int = int(time_str.split("s")[0]);
    } elif time_str.endswith("m") {
        time_int = int(time_str.split("m")[0]) * 60;
    } elif time_str.endswith("h") {
        time_int = int(time_str.split("h")[0]) * 60 * 60;
    } else {
        raise Exception("%s not support" % time_str);
    }
    time_int
}

"""Flatten results with error, returning first exception and all results."""
def _flatten_results_with_err(results_with_err: list[tuple[any, any]]) -> tuple[any, list[any]] {
    err_msg_list: list[str] = [];
    results: list[any] = [];
    for (idx, (each_err, each_result)) in enumerate(results_with_err) {
        if each_err {
            err_msg_list.append('(%s/%s) e: %s' % (idx, len(results_with_err), each_err));
        }
        results.append(each_result);
    }
    err = None if not err_msg_list else Exception(','.join(err_msg_list));
    if err {
        return (err, results);
    }
    return (None, results);
}

