"""
>>> factorial(5)
120
>>> factorial(4)
24
"""
def factorial(n: int) -> int {
    resultado = 1;
    for i in range(1, n + 1) {
        resultado = resultado * i;
    }
    return resultado;
}

glob INT64_MAX = (1 << 63) - 1;
glob INT32_MAX = (1 << 31) - 1;
glob UINT32_MASK = 0xFFFFFFFF;
glob UINT64_MOD = 1 << 64;
glob UINT32_MOD = 1 << 32;

"""Convert SipHash24 output to Py_hash_t."""
def pysiphash(uint64: int) -> tuple[int, int] {
    assert 0 <= uint64 < UINT64_MOD;
    if uint64 > INT64_MAX {
        int64 = uint64 - UINT64_MOD;
    } else {
        int64 = uint64;
    }
    uint32 = (uint64 ^ (uint64 >> 32)) & UINT32_MASK;
    if uint32 > INT32_MAX {
        int32 = uint32 - UINT32_MOD;
    } else {
        int32 = uint32;
    }
    return (int32, int64);
}

