"""Resolve URI to absolute URL, defaulting to localhost."""
def resolve_uri(uri: str) -> str {
    if not uri.startswith(('http://', 'https://')) {
        return '127.0.0.1%s' % uri;
    }
    return uri;
}

"""Scale relative risks for equivalence to a new reference group."""
def scale_relative_risks_for_equivalence(
    proportions: dict[str, float], relative_risks: dict[str, float]
) -> dict[str, float] {
    new_reference_deno = 0.0;
    for stratum in proportions.keys() {
        new_reference_deno += proportions[stratum] * relative_risks[stratum];
    }
    new_reference = 1.0 / new_reference_deno;
    for stratum in relative_risks.keys() {
        relative_risks[stratum] *= new_reference;
    }
    return relative_risks;
}

"""Return the requested byte range as a (left, right) tuple; None means open-ended."""

def __parse_request_range(range_header_text: str | None) -> tuple[int | None, int | None] {
    left = None;
    right = None;

    if range_header_text is None or not range_header_text {
        return (left, right);
    }

    range_header_text = range_header_text.strip();
    if not range_header_text.startswith("bytes") {
        return (left, right);
    }

    components = range_header_text.split("=");
    if len(components) != 2 {
        return (left, right);
    }

    components = components[1].split("-");

    try {
        right = int(components[1]);
    } except Exception as e {
        ;
    }

    try {
        left = int(components[0]);
    } except Exception as e {
        ;
    }

    return (left, right);
}

