glob NUM_INSTANCES = 15;
glob NUM_FUNCTIONS = 24;

"""Compute the problem index for the bbob suite with 15 instances and 24 functions."""
def encode_problem_index(function_idx: int, dimension_idx: int, instance_idx: int) -> int {
    return instance_idx + function_idx * NUM_INSTANCES + dimension_idx * NUM_INSTANCES * NUM_FUNCTIONS;
}

"""Calcula o maior divisor comum de dois valores"""
def greatest_common_divisor(value1: int, value2: int) -> int {
    value1 = abs(value1);
    value2 = abs(value2);

    if value1 < value2 {
        (value1, value2) = (value2, value1);
    }

    remainder = value1 % value2;

    if remainder == 0 {
        return value2;
    }

    return greatest_common_divisor(value2, remainder);
}

"""Calculate accuracy from confusion matrix counts."""
def calc_acc(fn: float, fp: float, tp: float, tn: float) -> float {
    return (tp + tn) / (tp + tn + fn + fp);
}

"""
    Create batches of features and labels
    :param batch_size: The batch size
    :param features: List of features
    :param labels: List of labels
    :return: Batches of (Features, Labels)
    """
def batches(batch_size: Any, features: Any, labels: Any) -> object {
    assert (len(features) == len(labels));
    output_batches = [];
    sample_size = len(features);
    for start_i in range(0, sample_size, batch_size) {
        end_i = start_i + batch_size;
        batch = [features[start_i:end_i], labels[start_i:end_i]];
        output_batches.append(batch);
    }
    return output_batches;
}

"""Returns the next player in an ordered list, cycling to the beginning at the end."""
def get_next_player(players: list[any], currentplayer: any) -> any {
    i = players.index(currentplayer) + 1;
    return players[i % len(players)];
}

