"""Get head indexes only for word-pieces tokenization."""
def preprocessing(list_of_tokens: list[list[any]], head_indexes_2d: list[list[int]]) -> list[list[any]] {
    batch_size = len(list_of_tokens);
    xx = [[]] * batch_size;
    for (i, tokens) in enumerate(list_of_tokens) {
        xx[i] = [0] * len(tokens);
        for (idx, item) in enumerate(head_indexes_2d[i]) {
            if item == 0 {
                xx[i][idx] = 0;
            } else {
                xx[i][idx] = tokens[item];
            }
        }
    }
    return xx;
}

"""Convert temperature from Fahrenheit to Celsius."""
