"""Calculate the dominant colors from a list of (count, (R, G, B, A)) tuples."""
def average_dominant_color(
    colors: list[tuple[int, tuple[int, int, int, int]]],
    mitigate: int = 175,
    max_margin: int = 140
) -> tuple[tuple[int, int, int], list[tuple[int, tuple[int, int, int, int]]]] {
    dominant_color = max(colors);
    dominant_rgb = dominant_color[1][:3];
    dominant_set = [dominant_color];
    remaining = [];

    total_count = sum(col[0] for col in colors);
    margin_val = max_margin * (1 - dominant_color[0] / total_count);
    margins = [margin_val] * 3;

    colors.remove(dominant_color);

    for color in colors {
        rgb = color[1];
        if (
            rgb[0] < dominant_rgb[0] + margins[0] and
            rgb[0] > dominant_rgb[0] - margins[0] and
            rgb[1] < dominant_rgb[1] + margins[1] and
            rgb[1] > dominant_rgb[1] - margins[1] and
            rgb[2] < dominant_rgb[2] + margins[2] and
            rgb[2] > dominant_rgb[2] - margins[2]
        ) {
            dominant_set.append(color);
        } else {
            remaining.append(color);
        }
    }

    dominant_avg = [];
    for band in range(3) {
        avg = 0;
        total = 0;
        for color in dominant_set {
            avg += color[0] * color[1][band];
            total += color[0];
        }
        dominant_avg.append(int(avg / total));
    }

    final_dominant = [];
    brightest = max(dominant_avg);
    for band in range(3) {
        value = dominant_avg[band] / (brightest / mitigate) if brightest > mitigate else dominant_avg[band];
        final_dominant.append(int(value));
    }

    return (tuple(final_dominant), remaining);
}
